import{_ as e,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1958年 · 市场亢奋中的冷静","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1958年.md","filePath":"05_quotes/by-year/1958年.md"}'),l={name:"05_quotes/by-year/1958年.md"};function u(q,t,c,s,_,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1958年-·-市场亢奋中的冷静" tabindex="-1">1958年 · 市场亢奋中的冷静 <a class="header-anchor" href="#_1958年-·-市场亢奋中的冷静" aria-label="Permalink to &quot;1958年 · 市场亢奋中的冷静&quot;">​</a></h1><blockquote><p>&quot;我无意预测整体市场——我的努力专注于寻找被低估的证券。&quot;——巴菲特（28岁）</p></blockquote><p>本页收录1958年致股东信中的经典语录。在市场亢奋、公众普遍认为买股票必然获利之时，巴菲特保持冷静，专注于被低估的证券。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;美国人特有的反复无常的性格在1958年发生了重大转变，&#39;亢奋&#39;这个词用来形容股市再合适不过了。&quot;</p></blockquote><blockquote><p>&quot;虽然无法确定他们会继续增加多久从而刺激价格上涨，但我认为可以合理地说，他们停留的时间越长，随后的反应就越大。&quot;</p></blockquote><blockquote><p>&quot;我无意预测整体市场——我的努力专注于寻找被低估的证券。&quot;</p></blockquote><blockquote><p>&quot;一旦出现这种情况，我认为即使是低估证券的价格也会受到实质性影响（虽然内在价值不会）。&quot;</p></blockquote><blockquote><p>&quot;在任何情况下，我们最大的持仓不超过各个合伙企业资产的10%至20%，我们希望这些股票保持平稳或下跌，这样我们才能积累更大的头寸。&quot;</p></blockquote><blockquote><p>&quot;像Commonwealth这样的情形最终实现盈利的年份，在很大程度上是偶然的。因此，任何单一年份的表现作为估计长期结果的基础都有严重的局限性。&quot;</p></blockquote><blockquote><p>&quot;我相信，投资于这类被低估且受良好保护的证券的项目，是获得证券长期利润的最可靠方式。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1958年，道琼斯指数从435点飙升至583点，全年涨幅38.5%，全民炒股情绪高涨。巴菲特在牛市狂热中逆势而行，专注于被低估的小型银行股Commonwealth Trust Co.，以50美元购入内在价值125美元的标的。他再次强调，牛市中落后指数是预期内的代价，真正的价值终将兑现。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1958年/翻译.html">01_letters/1958年/翻译</a> · <a href="/01_letters/1958年/核心总结.html">01_letters/1958年/核心总结</a> · <a href="/01_letters/1958年/思维导图.html">01_letters/1958年/思维导图</a></p>',18)])])}const b=e(l,[["render",u]]);export{n as __pageData,b as default};
